function tai_step_catalog($force) {
  $file = sys_get_temp_dir() . '/tai_blockrun_step_catalog.json';
  $now = time();
  if (!$force && is_file($file)) {
    $x = json_decode(@file_get_contents($file), true);
    if (is_array($x) && isset($x['saved_at']) && ($now-(int)$x['saved_at'])<45) return $x;
  }
  $r = tai_http_json('https://blockrun.ai/api/v1/models','GET',null,array(),8);
  $out = array('saved_at'=>$now,'ok'=>false,'free'=>false,'status'=>$r['status']);
  if ($r['ok']) {
    $rows = isset($r['data']['models']) && is_array($r['data']['models']) ? $r['data']['models'] : (isset($r['data']['data']) && is_array($r['data']['data']) ? $r['data']['data'] : array());
    $out['ok']=true;
    foreach ($rows as $m) {
      if (!is_array($m)) continue;
      $id = isset($m['id']) ? (string)$m['id'] : '';
      if ($id !== 'nvidia/step-3.7-flash') continue;
      $billing = isset($m['billingMode']) ? strtolower((string)$m['billingMode']) : (isset($m['billing_mode']) ? strtolower((string)$m['billing_mode']) : '');
      $zero = isset($m['inputPrice']) && isset($m['outputPrice']) && (float)$m['inputPrice']==0.0 && (float)$m['outputPrice']==0.0;
      if (!$zero && isset($m['input_price']) && isset($m['output_price'])) $zero=((float)$m['input_price']==0.0 && (float)$m['output_price']==0.0);
      $out['free'] = ($billing==='free' || $zero);
      $out['available'] = !isset($m['available']) || $m['available'] ? true : false;
      break;
    }
  }
  @file_put_contents($file,json_encode($out));
  return $out;
}
